from fastapi import APIRouter, Depends, HTTPException
from kubernetes_asyncio import client
import base64

router = APIRouter(prefix="/k8s/namespaces")

@router.get("/{namespace}/secrets/{secret_name}")
async def get_cluster_secret(
    namespace: str,
    secret_name: str,
    current_user: User = Depends(get_current_tenant_user),
    k8s_core_api: client.CoreV1Api = Depends(get_k8s_core_api)
):
    # Strictly enforce that the user only accesses their assigned tenant namespace
    if namespace not in current_user.assigned_namespaces:
        raise HTTPException(status_code=403, detail="Access to specified namespace is forbidden")

    try:
        secret = await k8s_core_api.read_namespaced_secret(
            name=secret_name,
            namespace=namespace
        )
    except client.exceptions.ApiException as e:
        if e.status == 404:
            raise HTTPException(status_code=404, detail="Secret not found")
        raise HTTPException(status_code=500, detail="Kubernetes API error")

    decoded_data = {}
    if secret.data:
        for k, v in secret.data.items():
            decoded_data[k] = base64.b64decode(v).decode("utf-8", errors="replace")

    return {
        "namespace": namespace,
        "secret_name": secret_name,
        "data": decoded_data
    }
